    fn release_inner<P: GttProfileV1, S: GttAllocationStateV1>(
        &mut self,
        token: &SharedGttAllocationV1<P, S>,
        expected: SharedAllocationPhaseV1,
        progress: &mut control_cleanup::NativeDisposalProgressV1,
    ) -> Result<(), MemorySessionError> {
        let index = self.index(token, expected)?;
        self.check_currentness()?;
        if self.allocations[index].free_attempted {
            return self.quarantine(MemorySessionError::KernelResultMalformed(
                "shared FREE_MEMORY_OF_GPU exactly-once",
            ));
        }
        if P::IS_USERPTR {
            let handle = self.allocations[index]
                .handle
                .ok_or(MemorySessionError::InvalidAllocationAuthority)?;
            self.allocations[index].free_attempted = true;
            progress.free.attempted = true;
            let result = self.backend.free(handle);
            progress.free.returned_success = Some(result.is_ok());
            if let Err(error) = result {
                return self.quarantine(error);
            }
            self.allocations[index].handle = None;
            self.check_currentness()?;
            let unmap_result = {
                let (backend, allocations) = (&mut self.backend, &mut self.allocations);
                let mapping = allocations[index]
                    .mapping
                    .as_mut()
                    .ok_or(MemorySessionError::InvalidAllocationAuthority)?;
                progress.cpu_unmap.attempted = true;
                let result = backend.unmap_cpu(mapping);
                progress.cpu_unmap.returned_success = Some(result.is_ok());
                result
            };
            if let Err(error) = unmap_result {
                return self.quarantine(error);
            }
            self.allocations[index].mapping = None;
            self.check_currentness()?;
            if self.allocations[index].reservation.take().is_none() {
                return self.quarantine(MemorySessionError::InvalidAllocationAuthority);
            }
            progress.native_disposed = true;
            self.check_currentness()?;
            self.allocations[index].phase = SharedAllocationPhaseV1::Released;
            self.allocation_record_slots.remove(&token.id);
            self.retained_gpu_va_bytes = self
                .retained_gpu_va_bytes
                .checked_sub(token.layout.gpu_va_bytes)
                .ok_or(MemorySessionError::KernelResultMalformed(
                    "shared retained GPU VA accounting",
                ))?;
            return Ok(());
        }
        let unmap_result = {
            let (backend, allocations) = (&mut self.backend, &mut self.allocations);
            let mapping = allocations[index]
                .mapping
                .as_mut()
                .ok_or(MemorySessionError::InvalidAllocationAuthority)?;
            progress.cpu_unmap.attempted = true;
            let result = backend.unmap_cpu(mapping);
            progress.cpu_unmap.returned_success = Some(result.is_ok());
            result
        };
        if let Err(error) = unmap_result {
            return self.quarantine(error);
        }
        self.allocations[index].mapping = None;
        self.check_currentness()?;
        let handle = self.allocations[index]
            .handle
            .ok_or(MemorySessionError::InvalidAllocationAuthority)?;
        self.allocations[index].free_attempted = true;
        progress.free.attempted = true;
        let result = self.backend.free(handle);
        progress.free.returned_success = Some(result.is_ok());
        if let Err(error) = result {
            return self.quarantine(error);
        }
        self.allocations[index].handle = None;
        self.check_currentness()?;
        let release_reservation = {
            let (backend, allocations) = (&mut self.backend, &mut self.allocations);
            let reservation = allocations[index]
                .reservation
                .as_mut()
                .ok_or(MemorySessionError::InvalidAllocationAuthority)?;
            progress.va_release.attempted = true;
            let result = backend.release_va_reservation(reservation);
            progress.va_release.returned_success = Some(result.is_ok());
            result
        };
        if let Err(error) = release_reservation {
            return self.quarantine(error);
        }
        progress.native_disposed = true;
        self.allocations[index].reservation = None;
        self.check_currentness()?;
        self.allocations[index].phase = SharedAllocationPhaseV1::Released;
        self.allocation_record_slots.remove(&token.id);
        self.retained_gpu_va_bytes = match self
            .retained_gpu_va_bytes
            .checked_sub(token.layout.gpu_va_bytes)
        {
            Some(bytes) => bytes,
            None => {
                let error =
                    MemorySessionError::KernelResultMalformed("shared retained GPU VA accounting");
                return if self.host_backing_account.is_some() && is_host_backing_profile::<P>() {
                    self.quarantine(error)
                } else {
                    Err(error)
                };
            }
        };
        if let Some(charge) = self.allocations[index].host_backing_charge.take() {
            let Some(account) = &self.host_backing_account else {
                return self.quarantine(MemorySessionError::InvalidAllocationAuthority);
            };
            let (device, vm) = account.domain();
            if let Err(error) = charge.release_after_disposal(
                account,
                self.session_id,
                device,
                vm,
                token.id,
                token.generation,
                token.layout,
            ) {
                return self.quarantine(host_backing_accounting_error(error));
            }
        }
        Ok(())
    }
}

fn preflight_queue_foundation_native_memory_transition_v1<B: MemoryBackend>(
    foundation: &QueueModelFoundationV1,
    engine: &mut SharedMemoryEngine<B>,
    needed: u64,
    process_poison: impl FnOnce(),
) -> Result<(), MemorySessionError> {
    match foundation.preflight_memory_transition_revisions(needed) {
        Ok(()) => Ok(()),
        Err(error) => {
            process_poison();
            engine.quarantine(MemorySessionError::Model(error))
        }
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct PublicDeviceInitializationPlanV1 {
    chunk_bytes: usize,
    chunk_count: usize,
}

fn public_device_initialization_worker_count(byte_len: usize, available_workers: usize) -> usize {
    if byte_len == 0 {
        return 0;
    }
    if byte_len < PUBLIC_DEVICE_PARALLEL_FILL_THRESHOLD_BYTES_V1 {
        return 1;
    }
    let useful_workers = byte_len.div_ceil(PUBLIC_DEVICE_PARALLEL_FILL_BYTES_PER_WORKER_V1);
    available_workers
        .clamp(1, MAX_PUBLIC_DEVICE_PARALLEL_FILL_WORKERS_V1)
        .min(useful_workers)
}

fn public_device_initialization_plan(
    byte_len: usize,
    requested_workers: usize,
) -> Option<PublicDeviceInitializationPlanV1> {
    if byte_len == 0 {
        return None;
    }
    let worker_limit = requested_workers
        .clamp(1, MAX_PUBLIC_DEVICE_PARALLEL_FILL_WORKERS_V1)
        .min(byte_len);
    let chunk_bytes = byte_len.div_ceil(worker_limit);
    Some(PublicDeviceInitializationPlanV1 {
        chunk_bytes,
        chunk_count: byte_len.div_ceil(chunk_bytes),
    })
}

/// Copies an authenticated source into a public device mapping using bounded,
/// disjoint safe slices. The source remains owned by the caller until the
/// distinct readback comparison completes.
fn copy_public_device_mapping(
    destination: &mut [u8],
    source: &[u8],
) -> Result<(), MemorySessionError> {
    let available_workers = std::thread::available_parallelism().map_or(1, usize::from);
    let worker_count =
        public_device_initialization_worker_count(destination.len(), available_workers);
    write_disjoint_source_partitions(
        destination,
        source,
        worker_count,
        |_| true,
        |destination, source| destination.copy_from_slice(source),
    )
}

/// Performs a second, complete read of the mapped logical extent and compares
/// every byte with the retained authenticated source before CPU unmapping.
fn verify_public_device_mapping(mapped: &[u8], source: &[u8]) -> Result<(), MemorySessionError> {
    let available_workers = std::thread::available_parallelism().map_or(1, usize::from);
    let worker_count = public_device_initialization_worker_count(mapped.len(), available_workers);
    verify_disjoint_source_partitions(mapped, source, worker_count, |_| true, exact_bytes_match)
}

fn exact_bytes_match(left: &[u8], right: &[u8]) -> bool {
    left.len() == right.len()
        && left
            .iter()
            .zip(right)
            .fold(0_u8, |difference, (left, right)| {
                difference | (left ^ right)
            })
            == 0
}

fn write_disjoint_source_partitions(
    destination: &mut [u8],
    source: &[u8],
    requested_workers: usize,
    allow_spawn: impl Fn(usize) -> bool + Copy + Send + Sync,
    write: impl Fn(&mut [u8], &[u8]) + Copy + Send + Sync,
) -> Result<(), MemorySessionError> {
    if destination.len() != source.len() {
        return Err(MemorySessionError::DeviceContentMismatch);
    }
    let Some(plan) = public_device_initialization_plan(destination.len(), requested_workers) else {
        return Ok(());
    };
    let outcome = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        if plan.chunk_count == 1 {
            write(destination, source);
            return Ok(());
        }
        std::thread::scope(|scope| {
            for (index, (destination, source)) in destination
                .chunks_mut(plan.chunk_bytes)
                .zip(source.chunks(plan.chunk_bytes))
                .enumerate()
            {
                if !allow_spawn(index) {
                    return Err(MemorySessionError::DeviceInitializationWriteFailed);
                }
                std::thread::Builder::new()
                    .spawn_scoped(scope, move || write(destination, source))
                    .map_err(|_| MemorySessionError::DeviceInitializationWriteFailed)?;
            }
            Ok(())
        })
    }));
    match outcome {
        Ok(result) => result,
        Err(_) => Err(MemorySessionError::DeviceInitializationWriteFailed),
    }
}

fn verify_disjoint_source_partitions(
    mapped: &[u8],
    source: &[u8],
    requested_workers: usize,
    allow_spawn: impl Fn(usize) -> bool + Copy + Send + Sync,
    compare: impl Fn(&[u8], &[u8]) -> bool + Copy + Send + Sync,
) -> Result<(), MemorySessionError> {
    if mapped.len() != source.len() {
        return Err(MemorySessionError::DeviceContentMismatch);
    }
    let Some(plan) = public_device_initialization_plan(mapped.len(), requested_workers) else {
        return Ok(());
    };
    let all_equal = AtomicBool::new(true);
    let outcome = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        if plan.chunk_count == 1 {
            all_equal.store(compare(mapped, source), Ordering::Relaxed);
            return Ok(());
        }
        std::thread::scope(|scope| {
            for (index, (mapped, source)) in mapped
                .chunks(plan.chunk_bytes)
                .zip(source.chunks(plan.chunk_bytes))
                .enumerate()
            {
                if !allow_spawn(index) {
                    return Err(MemorySessionError::DeviceInitializationVerificationFailed);
                }
                let all_equal = &all_equal;
                std::thread::Builder::new()
                    .spawn_scoped(scope, move || {
                        if !compare(mapped, source) {
                            all_equal.store(false, Ordering::Relaxed);
                        }
                    })
                    .map_err(|_| MemorySessionError::DeviceInitializationVerificationFailed)?;
            }
            Ok(())
        })
    }));
    match outcome {
        Ok(Ok(())) if all_equal.load(Ordering::Relaxed) => Ok(()),
        Ok(Ok(())) => Err(MemorySessionError::DeviceContentMismatch),
        Ok(Err(error)) => Err(error),
        Err(_) => Err(MemorySessionError::DeviceInitializationVerificationFailed),
    }
}

/// Fills a public device-local CPU mapping using only disjoint safe slices.
///
/// Thread count and chunk size are bounded before any worker is started. A
/// spawn failure leaves the allocation retained and is promoted by the caller
/// to whole-session quarantine, so partial initialization cannot mint content
/// authority.
fn fill_public_device_mapping(
    bytes: &mut [u8],
    repeated_byte: u8,
) -> Result<(), MemorySessionError> {
    let available_workers = std::thread::available_parallelism().map_or(1, usize::from);
    let worker_count = public_device_initialization_worker_count(bytes.len(), available_workers);
    fill_repeated_byte_with_workers(bytes, repeated_byte, worker_count)
}

fn fill_repeated_byte_with_workers(
    bytes: &mut [u8],
    repeated_byte: u8,
    requested_workers: usize,
) -> Result<(), MemorySessionError> {
    write_disjoint_repeated_byte_partitions(bytes, requested_workers, move |chunk| {
        chunk.fill(repeated_byte);
    })
}

fn write_disjoint_repeated_byte_partitions(
    bytes: &mut [u8],
    requested_workers: usize,
    write: impl Fn(&mut [u8]) + Copy + Send + Sync,
) -> Result<(), MemorySessionError> {
    let Some(plan) = public_device_initialization_plan(bytes.len(), requested_workers) else {
        return Ok(());
    };
    let outcome = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        if plan.chunk_count == 1 {
            write(bytes);
            return Ok(());
        }
        std::thread::scope(|scope| {
            for chunk in bytes.chunks_mut(plan.chunk_bytes) {
                std::thread::Builder::new()
                    .spawn_scoped(scope, move || write(chunk))
                    .map_err(|_| MemorySessionError::DeviceInitializationWriteFailed)?;
            }
            Ok(())
        })
    }));
    match outcome {
        Ok(result) => result,
        Err(_) => Err(MemorySessionError::DeviceInitializationWriteFailed),
    }
}

impl<B: MemoryBackend> Drop for SharedMemoryEngine<B> {
    fn drop(&mut self) {
        // Native cleanup and destructive FREE are always explicit. Drop never
        // retries an operation whose kernel result could be ambiguous.
    }
}

// Private fields and unique ownership bind validation to the exact allocation
// that is later copied. Safe callers cannot mutate or substitute its bytes.
struct ValidatedInitializationSourceV1 {
    bytes: Box<[u8]>,
    byte_len: u64,
    content: Gfx942DeviceContentDescriptorV1,
}

impl ValidatedInitializationSourceV1 {
    fn bytes(&self) -> &[u8] {
        &self.bytes
    }

    const fn byte_len(&self) -> u64 {
        self.byte_len
    }

    const fn content(&self) -> Gfx942DeviceContentDescriptorV1 {
        self.content
    }
}

#[cfg(test)]
fn validate_initialization_source(
    bytes: Box<[u8]>,
    content: Gfx942DeviceContentDescriptorV1,
) -> Result<ValidatedInitializationSourceV1, MemorySessionError> {
    let byte_len = validate_initialization_source_bytes(&bytes, content)?;
    Ok(ValidatedInitializationSourceV1 {
        bytes,
        byte_len,
        content,
    })
}

fn validate_initialization_source_bytes(
    bytes: &[u8],
    content: Gfx942DeviceContentDescriptorV1,
) -> Result<u64, MemorySessionError> {
    let byte_len = u64::try_from(bytes.len()).map_err(|_| MemorySessionError::SizeOverflow)?;
    let sha256: [u8; 32] = Sha256::digest(bytes).into();
    if byte_len == 0 || content.byte_len() != byte_len || content.sha256() != sha256 {
        return Err(MemorySessionError::DeviceContentMismatch);
    }
    Ok(byte_len)
}

pub(crate) fn device_memory_layout(
    requested_bytes: u64,
    alignment: u64,
    flags: KfdAllocMemoryFlags,
) -> Result<Gfx942DeviceMemoryLayoutV1, MemorySessionError> {
    if requested_bytes == 0 || requested_bytes > MAX_GFX942_DEVICE_MEMORY_BYTES_V1 {
        return Err(MemorySessionError::InvalidDeviceMemorySize);
    }
    if alignment == 0
        || !alignment.is_power_of_two()
        || alignment > MAX_GFX942_DEVICE_MEMORY_ALIGNMENT_V1
    {
        return Err(MemorySessionError::InvalidDeviceMemoryAlignment);
    }
    let backing_bytes = requested_bytes
        .checked_add(HOST_VISIBLE_MEMORY_PAGE_BYTES_V1 - 1)
        .ok_or(MemorySessionError::SizeOverflow)?
        / HOST_VISIBLE_MEMORY_PAGE_BYTES_V1
        * HOST_VISIBLE_MEMORY_PAGE_BYTES_V1;
    if backing_bytes > MAX_GFX942_DEVICE_MEMORY_BYTES_V1 {
        return Err(MemorySessionError::InvalidDeviceMemorySize);
    }
    if flags != KfdAllocMemoryFlags::DEVICE_LOCAL
        && flags != KfdAllocMemoryFlags::DEVICE_LOCAL_PUBLIC
    {
        return Err(MemorySessionError::InvalidDeviceMemoryAuthority);
    }
    Ok(Gfx942DeviceMemoryLayoutV1 {
        requested_bytes,
        backing_bytes,
        alignment,
        uapi_flags: flags.bits(),
    })
}

pub(crate) fn coherent_host_layout_v1(
    requested_bytes: usize,
) -> Result<SharedGttAllocationLayoutV1, MemorySessionError> {
    profile_layout::<HostVisibleCoherentGttV1>(requested_bytes)
}

fn profile_layout<P: GttProfileV1>(
    requested_bytes: usize,
) -> Result<SharedGttAllocationLayoutV1, MemorySessionError> {
    if requested_bytes == 0 {
        return Err(MemorySessionError::InvalidRequestedSize);
    }
    let requested = u64::try_from(requested_bytes).map_err(|_| MemorySessionError::SizeOverflow)?;
    let cpu_mapping_bytes = if P::KIND == MemoryKindV1::QueueStorage {
        if !(MIN_AQL_QUEUE_BYTES_V1..=MAX_AQL_QUEUE_BYTES_V1).contains(&requested)
            || !requested.is_power_of_two()
        {
            return Err(MemorySessionError::InvalidProfileSize(P::NAME));
        }
        requested
    } else {
        requested
            .checked_add(HOST_VISIBLE_MEMORY_PAGE_BYTES_V1 - 1)
            .map(|bytes| bytes & !(HOST_VISIBLE_MEMORY_PAGE_BYTES_V1 - 1))
            .ok_or(MemorySessionError::SizeOverflow)?
    };
    if cpu_mapping_bytes > MAX_SHARED_GTT_SINGLE_CPU_BYTES_V1 {
        return Err(MemorySessionError::InvalidProfileSize(P::NAME));
    }
    let gpu_va_bytes = if P::FLAGS.bits() & KFD_IOC_ALLOC_MEM_FLAGS_AQL_QUEUE_MEM != 0 {
        cpu_mapping_bytes
            .checked_mul(2)
            .ok_or(MemorySessionError::SizeOverflow)?
    } else {
        cpu_mapping_bytes
    };
    Ok(SharedGttAllocationLayoutV1 {
        profile: P::PROFILE,
        requested_bytes,
        cpu_mapping_bytes: usize::try_from(cpu_mapping_bytes)
            .map_err(|_| MemorySessionError::SizeOverflow)?,
        gpu_va_bytes,
        uapi_flags: P::FLAGS.bits(),
    })
}

fn validate_gpu_va_range(
    base: u64,
    byte_len: u64,
    aperture: crate::InclusiveAperture,
) -> Result<(), MemorySessionError> {
    if !base.is_multiple_of(HOST_VISIBLE_MEMORY_PAGE_BYTES_V1) {
        return Err(MemorySessionError::AddressNotPageAligned);
    }
    let end = base
        .checked_add(byte_len)
        .ok_or(MemorySessionError::AddressOutsideAperture)?;
    let aperture_end = aperture
        .limit()
        .checked_add(1)
        .ok_or(MemorySessionError::AddressOutsideAperture)?;
    if byte_len == 0 || base < aperture.base() || end > aperture_end {
        return Err(MemorySessionError::AddressOutsideAperture);
    }
    Ok(())
}

fn ranges_overlap(left: u64, left_len: u64, right: u64, right_len: u64) -> bool {
    let Some(left_end) = left.checked_add(left_len) else {
        return true;
    };
    let Some(right_end) = right.checked_add(right_len) else {
        return true;
    };
    left < right_end && right < left_end
}

#[cfg(all(target_os = "linux", target_arch = "x86_64"))]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum QueueModelOwnershipPhaseV1 {
    SessionOwned,
    QueueOwned { issuer: u64 },
    SessionOwnedLiveLoan { issuer: u64, generation: u64 },
}

#[cfg(all(target_os = "linux", target_arch = "x86_64"))]
pub(crate) struct LiveQueueModelFoundationLoanV1 {
    session_id: u64,
    issuer: u64,
    generation: u64,
    starting_revision: u64,
}

#[cfg(all(target_os = "linux", target_arch = "x86_64"))]
struct QueueModelOwnershipV1 {
    phase: QueueModelOwnershipPhaseV1,
    next_live_loan_generation: u64,
}

#[cfg(all(target_os = "linux", target_arch = "x86_64"))]
impl QueueModelOwnershipV1 {
    const fn new() -> Self {
        Self {
            phase: QueueModelOwnershipPhaseV1::SessionOwned,
            next_live_loan_generation: 1,
        }
    }

    const fn is_session_owned(&self) -> bool {
        matches!(self.phase, QueueModelOwnershipPhaseV1::SessionOwned)
    }

    const fn queue_owned_issuer(&self) -> Option<u64> {
        match self.phase {
            QueueModelOwnershipPhaseV1::QueueOwned { issuer } => Some(issuer),
            _ => None,
        }
    }

    fn configure_optional_device_backing_budget<B: MemoryBackend>(
        &self,
        engine: &mut SharedMemoryEngine<B>,
        device: ModelDeviceAdmissionV1,
        vm: VmKeyV1,
        budget: Option<Gfx942DeviceBackingBudgetV1>,
    ) -> Result<(), MemorySessionError> {
        let Some(budget) = budget else {
            return Ok(());
        };
        if !self.is_session_owned() {
            return Err(MemorySessionError::DeviceBackingBudgetConfiguration(
                "queue-owned or loaned memory cannot configure a backing budget",
            ));
        }
        engine.configure_device_backing_budget_v1(device.model_key(), vm, budget)
    }

    fn configure_optional_host_visible_backing_budget<B: MemoryBackend>(
        &self,
        engine: &mut SharedMemoryEngine<B>,
        device: ModelDeviceAdmissionV1,
        vm: VmKeyV1,
        budget: Option<Gfx942HostVisibleBackingBudgetV1>,
    ) -> Result<(), MemorySessionError> {
        let Some(budget) = budget else {
            return Ok(());
        };
        if !self.is_session_owned() {
            return Err(MemorySessionError::HostVisibleBackingBudgetConfiguration(
                "queue-owned or loaned memory cannot configure a backing budget",
            ));
        }
        engine.configure_host_visible_backing_budget_v1(device.model_key(), vm, budget)
    }

    fn take_foundation<B: MemoryBackend>(
        &mut self,
        engine: &mut SharedMemoryEngine<B>,
        foundation: &mut QueueModelFoundationV1,
        device: ModelDeviceAdmissionV1,
        vm: VmKeyV1,
    ) -> Result<QueueModelFoundationV1, MemorySessionError> {
        engine.device_backing_configuration_closed = true;
        engine.host_backing_configuration_closed = true;
        let issuer = self
            .certify_and_transfer_to_queue(foundation, engine.session_id, device, vm)
            .map_err(MemorySessionError::Model)?;
        debug_assert_eq!(self.queue_owned_issuer(), Some(issuer));
        let domain = foundation.memory().domain_id();
        Ok(core::mem::replace(
            foundation,
            QueueModelFoundationV1::empty(domain),
        ))
    }

    fn restore_foundation<B: MemoryBackend>(
        &mut self,
        engine: &mut SharedMemoryEngine<B>,
        session_foundation: &mut QueueModelFoundationV1,
        foundation: QueueModelFoundationV1,
        device: ModelDeviceAdmissionV1,
        vm: VmKeyV1,
    ) -> Result<(), MemorySessionError> {
        let issuer = self.queue_owned_issuer().ok_or(MemorySessionError::Model(
            "shared queue foundation ownership phase",
        ))?;
        if foundation
            .validate_full(engine.session_id, device, vm, issuer)
            .is_err()
            || self.restore_to_session(issuer).is_err()
        {
            return engine.quarantine(MemorySessionError::Model(
                "shared queue model ownership restoration",
            ));
        }
        let mut foundation = foundation;
        foundation
            .revoke_invariant_certificate(engine.session_id, device, vm, issuer)
            .expect("fully validated exact foundation certificate remains revocable");
        *session_foundation = foundation;
        Ok(())
    }

    fn certify_and_transfer_to_queue(
        &mut self,
        foundation: &mut QueueModelFoundationV1,
        session_id: u64,
        device: ModelDeviceAdmissionV1,
        vm: VmKeyV1,
    ) -> Result<u64, &'static str> {
        if !self.is_session_owned() {
            return Err("shared queue model ownership already transferred");
        }
        let issuer = foundation.mint_invariant_certificate(session_id, device, vm)?;
        // A fresh issuer defines a new loan-generation namespace, so tokens
        // from the prior queue occurrence remain stale even when numbering
        // restarts at one.
        self.next_live_loan_generation = 1;
        self.phase = QueueModelOwnershipPhaseV1::QueueOwned { issuer };
        Ok(issuer)
    }

    #[cfg(test)]
    fn transfer_to_queue(&mut self, issuer: u64) -> Result<(), ()> {
        if self.phase != QueueModelOwnershipPhaseV1::SessionOwned || issuer == 0 {
            return Err(());
        }
        self.phase = QueueModelOwnershipPhaseV1::QueueOwned { issuer };
        Ok(())
    }

    fn begin_live_loan(
        &mut self,
        session_id: u64,
        foundation: &mut QueueModelFoundationV1,
        device: ModelDeviceAdmissionV1,
        vm: VmKeyV1,
    ) -> Result<LiveQueueModelFoundationLoanV1, ()> {
        let QueueModelOwnershipPhaseV1::QueueOwned { issuer } = self.phase else {
            return Err(());
        };
        let generation = self.next_live_loan_generation;
        let next_generation = generation.checked_add(1).ok_or(())?;
        let starting_revision = foundation
            .begin_live_loan(session_id, device, vm, issuer, generation)
            .map_err(|_| ())?;
        self.next_live_loan_generation = next_generation;
        self.phase = QueueModelOwnershipPhaseV1::SessionOwnedLiveLoan { issuer, generation };
        Ok(LiveQueueModelFoundationLoanV1 {
            session_id,
            issuer,
            generation,
            starting_revision,
        })
    }

    fn finish_live_loan(
        &mut self,
        session_id: u64,
        foundation: &QueueModelFoundationV1,
        device: ModelDeviceAdmissionV1,
        vm: VmKeyV1,
        loan: LiveQueueModelFoundationLoanV1,
    ) -> Result<(), ()> {
        if loan.session_id != session_id
            || self.phase
                != (QueueModelOwnershipPhaseV1::SessionOwnedLiveLoan {
                    issuer: loan.issuer,
                    generation: loan.generation,
                })
        {
            return Err(());
        }
        foundation
            .authenticate_live_loan(
                session_id,
                device,
                vm,
                loan.issuer,
                loan.generation,
                loan.starting_revision,
            )
            .map_err(|_| ())?;
        self.phase = QueueModelOwnershipPhaseV1::QueueOwned {
            issuer: loan.issuer,
        };
        Ok(())
    }

    fn loan_foundation(
        &mut self,
        session_id: u64,
        session_foundation: &mut QueueModelFoundationV1,
        queue_foundation: &mut QueueModelFoundationV1,
        device: ModelDeviceAdmissionV1,
        vm: VmKeyV1,
    ) -> Result<LiveQueueModelFoundationLoanV1, ()> {
        let loan = self.begin_live_loan(session_id, queue_foundation, device, vm)?;
        core::mem::swap(session_foundation, queue_foundation);
        Ok(loan)
    }

    fn reclaim_foundation(
        &mut self,
        session_id: u64,
        session_foundation: &mut QueueModelFoundationV1,
        queue_foundation: &mut QueueModelFoundationV1,
        device: ModelDeviceAdmissionV1,
        vm: VmKeyV1,
        loan: LiveQueueModelFoundationLoanV1,
    ) -> Result<(), ()> {
        self.finish_live_loan(session_id, session_foundation, device, vm, loan)?;
        core::mem::swap(session_foundation, queue_foundation);
        Ok(())
    }

    fn restore_to_session(&mut self, issuer: u64) -> Result<(), ()> {
        if self.phase != (QueueModelOwnershipPhaseV1::QueueOwned { issuer }) {
            return Err(());
        }
        self.phase = QueueModelOwnershipPhaseV1::SessionOwned;
        Ok(())
    }
}

pub(crate) struct CoherentInitializationCustodyV1 {
    started: bool,
    completed: Option<Gfx942InitializedHostVisibleMemoryV1>,
}

impl CoherentInitializationCustodyV1 {
    pub(crate) const fn new() -> Self {
        Self {
            started: false,
            completed: None,
        }
    }

    pub(crate) fn completed(
        &self,
    ) -> Result<&Gfx942InitializedHostVisibleMemoryV1, MemorySessionError> {
        self.completed
            .as_ref()
            .ok_or(MemorySessionError::InvalidAllocationAuthority)
    }

    pub(crate) fn take_complete(
        &mut self,
    ) -> Result<Gfx942InitializedHostVisibleMemoryV1, MemorySessionError> {
        self.completed
            .take()
            .ok_or(MemorySessionError::InvalidAllocationAuthority)
    }

    pub(crate) fn requires_retention(&self) -> bool {
        self.completed.is_some()
    }

    fn prepare_with_memory(
        &mut self,
        memory: &mut impl coherent_initialization::CoherentInitializationV1,
        source: &[u8],
    ) -> Result<(), MemorySessionError> {
        if core::mem::replace(&mut self.started, true) {
            return Err(MemorySessionError::InvalidAllocationAuthority);
        }
        self.completed = Some(coherent_initialization::initialize_v1(memory, source)?);
        Ok(())
    }

    fn retain_with_engine<B: MemoryBackend>(self, engine: &mut SharedMemoryEngine<B>) {
        if let Some(completed) = self.completed {
            transitions::retain_coherent_insertion_output_v1(engine, completed.into_token());
        }
    }
}

pub(crate) struct CoherentAllocationCustodyV1 {
    started: bool,
    completed: Option<coherent_initialization::MappedAllocation>,
}

impl CoherentAllocationCustodyV1 {
    pub(crate) const fn new() -> Self {
        Self {
            started: false,
            completed: None,
        }
    }

    pub(crate) fn completed(
        &self,
    ) -> Result<&coherent_initialization::MappedAllocation, MemorySessionError> {
        self.completed
            .as_ref()
            .ok_or(MemorySessionError::InvalidAllocationAuthority)
    }

    pub(crate) fn take_complete(
        &mut self,
    ) -> Result<coherent_initialization::MappedAllocation, MemorySessionError> {
        self.completed
            .take()
            .ok_or(MemorySessionError::InvalidAllocationAuthority)
    }

    pub(crate) fn requires_retention(&self) -> bool {
        self.completed.is_some()
    }

    fn prepare_with_memory(
        &mut self,
        memory: &mut impl coherent_initialization::CoherentInitializationV1,
        requested_bytes: usize,
    ) -> Result<(), MemorySessionError> {
        if core::mem::replace(&mut self.started, true) {
            return Err(MemorySessionError::InvalidAllocationAuthority);
