        let issuer = self
            .model_ownership
            .queue_owned_issuer()
            .ok_or(MemorySessionError::Model(
                "shared queue foundation ownership phase",
            ))?;
        foundation
            .authenticate(self.engine.session_id, self.model_device, self.vm, issuer)
            .map_err(MemorySessionError::Model)
