        for (byte_len, repeated_byte) in [(1_u64, 0_u8), (4096, 0x5a), (4097, 0xff)] {
            let mut engine = acquired();
            let (device, vm) = device_vm(7);
            let initialization = repeated_content(byte_len, repeated_byte);
            let lease = engine
                .allocate_device_memory_with_flags(
                    device,
                    vm,
